     1	using System.Text.Json;
     2	
     3	namespace WovenMonopoly;
     4	
     5	public sealed class Game
     6	{
     7	    private static readonly string[] PlayerNames = ["Peter", "Billy", "Charlotte", "Sweedal"];
     8	    private const int StartingMoney = 16;
     9	    private const int PassGoBonus = 1;
    10	
    11	    private readonly Board _board;
    12	    private readonly int[] _rolls;
    13	    private readonly List<Player> _players;
    14	    private readonly Dictionary<PropertySpace, Player> _owners = [];
    15	    private bool _hasPlayed;
    16	
    17	    public Game(Board board, int[] rolls)
    18	    {
    19	        if (rolls.Any(roll => roll <= 0))
    20	            throw new GameInputException("rolls must be a JSON array of positive whole numbers");
    21	        _board = board;
    22	        _rolls = rolls;
    23	        _players = PlayerNames.Select(name => new Player(name, StartingMoney, board.GoIndex)).ToList();
    24	    }
    25	
    26	    public static int[] LoadRolls(string path)
    27	    {
    28	        string text;
    29	        try { text = File.ReadAllText(path); }
    30	        catch (IOException exception) { throw new GameInputException($"could not read rolls file '{path}': {exception.Message}"); }
    31	        catch (UnauthorizedAccessException exception) { throw new GameInputException($"could not read rolls file '{path}': {exception.Message}"); }
    32	
    33	        try
    34	        {
    35	            using var document = JsonDocument.Parse(text);
    36	            if (document.RootElement.ValueKind != JsonValueKind.Array)
    37	                throw new GameInputException("rolls must be a JSON array of positive whole numbers");
    38	            return document.RootElement.EnumerateArray().Select(element =>
    39	            {
    40	                if (!element.TryGetInt32(out var roll) || roll <= 0)
    41	                    throw new GameInputException("rolls must be a JSON array of positive whole numbers");
    42	                return roll;
    43	            }).ToArray();
    44	        }
    45	        catch (JsonException exception)
    46	        {
    47	            throw new GameInputException($"rolls file is not valid JSON: {exception.Message}");
    48	        }
    49	    }
    50	
    51	    public GameResult Play()
    52	    {
    53	        if (_hasPlayed) throw new InvalidOperationException("A game instance can only be played once.");
    54	        _hasPlayed = true;
    55	        var rollsPlayed = 0;
    56	        for (var turn = 0; turn < _rolls.Length; turn++)
    57	        {
    58	            var player = _players[turn % _players.Count];
    59	            var (position, goPasses) = _board.Advance(player.Position, _rolls[turn]);
    60	            player.Position = position;
    61	            player.Receive(goPasses * PassGoBonus);
    62	            ResolveLanding(player);
    63	            rollsPlayed++;
    64	            if (player.IsBankrupt) break;
    65	        }
    66	
    67	        var eligible = _players.Where(player => !player.IsBankrupt).ToList();
    68	        if (eligible.Count == 0) eligible = _players;
    69	        var highestMoney = eligible.Max(player => player.Money);
    70	        var winners = eligible.Where(player => player.Money == highestMoney).Select(player => player.Name).ToArray();
    71	        var playerResults = _players.Select(player => new PlayerResult(
    72	            player.Name, player.Money, _board[player.Position].Name, player.IsBankrupt)).ToArray();
    73	        return new GameResult(winners, playerResults, _players.FirstOrDefault(player => player.IsBankrupt)?.Name,
    74	            rollsPlayed, _rolls.Length);
    75	    }
    76	
    77	    private void ResolveLanding(Player player)
    78	    {
    79	        if (_board[player.Position] is not PropertySpace property) return;
    80	        if (!_owners.TryGetValue(property, out var owner))
    81	        {
    82	            var paid = player.Pay(property.Price);
    83	            if (paid == property.Price) _owners[property] = player;
    84	            return;
    85	        }
    86	        if (owner == player) return;
    87	
    88	        var ownsGroup = _board.ColourGroup(property.Colour).All(space =>
    89	            _owners.TryGetValue(space, out var groupOwner) && groupOwner == owner);
    90	        var rent = property.Price * (ownsGroup ? 2 : 1);
    91	        owner.Receive(player.Pay(rent));
    92	    }
    93	}
    94	
    95	public sealed class Player(string name, int money, int position)
    96	{
    97	    public string Name { get; } = name;
    98	    public int Money { get; private set; } = money;
    99	    public int Position { get; set; } = position;
   100	    public bool IsBankrupt { get; private set; }
   101	
   102	    public void Receive(int amount) => Money += amount;
   103	
   104	    public int Pay(int amount)
   105	    {
   106	        var paid = Math.Min(amount, Money);
   107	        Money -= paid;
   108	        if (paid < amount) IsBankrupt = true;
   109	        return paid;
   110	    }
   111	}
   112	
   113	public sealed record PlayerResult(string Name, int Money, string Space, bool Bankrupt);
   114	public sealed record GameResult(string[] Winners, PlayerResult[] Players, string? BankruptPlayer,
   115	    int RollsPlayed, int RollsTotal)
   116	{
   117	    public string EndedBy => BankruptPlayer is null ? "rolls_exhausted" : "bankruptcy";
   118	
   119	    public string Summary()
   120	    {
   121	        var verdict = Winners.Length == 1 ? $"Winner: {Winners[0]}" : $"Tie between: {string.Join(", ", Winners)}";
   122	        var reason = BankruptPlayer is null
   123	            ? $"all {RollsTotal} rolls were played and nobody went bankrupt"
   124	            : $"{BankruptPlayer} went bankrupt on roll {RollsPlayed} of {RollsTotal}";
   125	        var lines = new List<string> { $"{verdict} ({reason})", "" };
   126	        lines.AddRange(Players.Select(player =>
   127	            $"  {player.Name,-10} ${player.Money,-4} on {player.Space}{(player.Bankrupt ? "  (bankrupt)" : "")}"));
   128	        return string.Join(Environment.NewLine, lines);
   129	    }
   130	}
