// Ruby: lib/woven_monopoly/space.rb
using System.Text.Json;

namespace WovenMonopoly.Models;

// A square on the board. Each kind of space decides for itself what happens
// when a player lands on it, so a new kind of space (jail, tax, chance...) is
// a new subclass plus one line in Board.SpaceTypes.
public abstract class Space(string name)
{
    public string Name { get; } = name;

    // Hook called by the game after a player has finished moving onto the space.
    public virtual void Land(Game game, Player player) { }

    // Reads a required string from a space's JSON object, or explains what is wrong.
    protected static string RequireString(JsonElement attrs, string key)
    {
        if (attrs.TryGetProperty(key, out var value) && value.ValueKind == JsonValueKind.String)
            return value.GetString()!;

        throw new InvalidBoardException($"space {Describe(attrs)}: '{key}' must be a string, got {Raw(attrs, key)}");
    }

    protected static int RequireInt(JsonElement attrs, string key)
    {
        if (attrs.TryGetProperty(key, out var value) && value.ValueKind == JsonValueKind.Number &&
            value.TryGetInt32(out var number))
            return number;

        throw new InvalidBoardException($"space {Describe(attrs)}: '{key}' must be a whole number, got {Raw(attrs, key)}");
    }

    protected static string Describe(JsonElement attrs) =>
        attrs.TryGetProperty("name", out var name) ? name.GetRawText() : "(unnamed)";

    private static string Raw(JsonElement attrs, string key) =>
        attrs.TryGetProperty(key, out var value) ? value.GetRawText() : "nothing";
}

// The starting square. Passing it is handled by the board and the game, so
// landing on it does nothing extra.
public sealed class GoSpace(string name) : Space(name)
{
    public static GoSpace Build(JsonElement attrs) => new(RequireString(attrs, "name"));
}

// A square that must be bought when unowned and that charges rent when owned.
public sealed class PropertySpace(string name, int price, string colour) : Space(name)
{
    public int Price { get; } = price;
    public string Colour { get; } = colour;

    public static PropertySpace Build(JsonElement attrs)
    {
        var price = RequireInt(attrs, "price");
        if (price <= 0) throw new InvalidBoardException($"space {Describe(attrs)}: price must be positive");

        return new PropertySpace(RequireString(attrs, "name"), price, RequireString(attrs, "colour"));
    }

    public override void Land(Game game, Player player)
    {
        var owner = game.OwnerOf(this);
        if (owner is null)
            game.Buy(player, this);
        else if (owner != player)
            game.ChargeRent(player, owner, this);
    }
}

