namespace WovenMonopoly.Models;

public sealed class Player(string name, int money, int position = 0)
{
    public string Name { get; } = name;
    public int Money { get; private set; } = money;
    public int Position { get; set; } = position;
    public bool IsBankrupt { get; private set; }

    public void Receive(int amount) => Money += amount;

    // Pays as much of `amount` as the player has. A player who cannot cover the
    // full amount hands over everything they own and is bankrupt. Returns what
    // was actually paid so the caller can credit the right amount to the payee.
    public int Pay(int amount)
    {
        var paid = Math.Min(amount, Money);
        Money -= paid;
        if (paid < amount) IsBankrupt = true;
        return paid;
    }
}

