namespace WovenMonopoly.Models;

// Every number or policy the game rules fix lives here, so changing a rule
// (starting cash, GO bonus, how rent is worked out) does not touch the game loop.
// Create with defaults (new Rules()) or override some: new Rules { StartingMoney = 2 }.
public sealed class Rules
{
    public static readonly IReadOnlyList<string> DefaultPlayerNames = ["Peter", "Billy", "Charlotte", "Sweedal"];

    public IReadOnlyList<string> PlayerNames { get; init; } = DefaultPlayerNames;
    public int StartingMoney { get; init; } = 16;
    public int PassGoBonus { get; init; } = 1;

    // Rent for a property: its price, doubled when the owner holds every
    // property of its colour.
    public int Rent(PropertySpace property, bool ownsFullColourSet) =>
        ownsFullColourSet ? property.Price * 2 : property.Price;
}

