// Ruby: lib/woven_monopoly/game.rb
namespace WovenMonopoly.Models;

// Plays one deterministic game: players take turns using the next roll from a
// fixed list until someone goes bankrupt or the rolls run out.
public sealed class Game
{
    private readonly IReadOnlyList<int> _rolls;
    private readonly Rules _rules;
    private readonly Dictionary<PropertySpace, Player> _owners = []; // who owns what
    private int _rollsPlayed;

    public Board Board { get; }
    public IReadOnlyList<Player> Players { get; }

    public Game(Board board, IReadOnlyList<int> rolls, Rules? rules = null)
    {
        Board = board;
        _rolls = ValidateRolls(rolls);
        _rules = rules ?? new Rules();
        Players = _rules.PlayerNames
            .Select(name => new Player(name, _rules.StartingMoney, board.GoIndex))
            .ToList();
    }

    public GameResult Play()
    {
        for (var turn = 0; turn < _rolls.Count; turn++)
        {
            PlayTurn(Players[turn % Players.Count], _rolls[turn]);
            _rollsPlayed++;
            if (Players.Any(p => p.IsBankrupt)) break;
        }

        return BuildResult();
    }

    // --- Services the spaces use while resolving a landing -----------------

    public Player? OwnerOf(PropertySpace property) => _owners.GetValueOrDefault(property);

    public void Buy(Player player, PropertySpace property)
    {
        var paid = player.Pay(property.Price);
        if (paid == property.Price) _owners[property] = player;
    }

    public void ChargeRent(Player payer, Player owner, PropertySpace property)
    {
        var rent = _rules.Rent(property, ownsFullColourSet: OwnsFullColourSet(owner, property));
        owner.Receive(payer.Pay(rent));
    }

    private void PlayTurn(Player player, int roll)
    {
        (player.Position, var goPasses) = Board.Advance(player.Position, roll);
        player.Receive(goPasses * _rules.PassGoBonus);
        Board[player.Position].Land(this, player);
    }

    private bool OwnsFullColourSet(Player owner, PropertySpace property) =>
        Board.ColourGroup(property.Colour).All(p => OwnerOf(p) == owner);

    private static IReadOnlyList<int> ValidateRolls(IReadOnlyList<int> rolls)
    {
        if (rolls.Any(r => r <= 0))
            throw new InvalidRollsException("rolls must be a JSON array of positive whole numbers");

        return rolls;
    }

    private GameResult BuildResult() => new(
        Winners: Winners(),
        Players: Players.Select(p => new PlayerResult(p.Name, p.Money, Board[p.Position].Name, p.IsBankrupt)).ToList(),
        BankruptPlayer: Players.FirstOrDefault(p => p.IsBankrupt)?.Name,
        RollsPlayed: _rollsPlayed,
        RollsTotal: _rolls.Count);

    // The richest player wins; a bankrupt player cannot win. Ties are reported.
    private IReadOnlyList<string> Winners()
    {
        var eligible = Players.Where(p => !p.IsBankrupt).ToList();
        if (eligible.Count == 0) eligible = Players.ToList();
        var top = eligible.Max(p => p.Money);
        return eligible.Where(p => p.Money == top).Select(p => p.Name).ToList();
    }
}

