using System.Text.Json;

namespace WovenMonopoly.Models;

// An ordered, circular list of spaces. The board knows nothing about players
// or money; it only answers questions about layout.
public sealed class Board
{
    // Maps the "type" in board.json to the method that builds that kind of space.
    public static readonly IReadOnlyDictionary<string, Func<JsonElement, Space>> SpaceTypes =
        new Dictionary<string, Func<JsonElement, Space>>
        {
            ["go"] = GoSpace.Build,
            ["property"] = PropertySpace.Build
        };

    private readonly Space[] _spaces;

    public Board(IEnumerable<Space> spaces)
    {
        _spaces = spaces.ToArray();
        var goIndexes = Enumerable.Range(0, _spaces.Length).Where(i => _spaces[i] is GoSpace).ToList();
        if (goIndexes.Count != 1)
            throw new InvalidBoardException($"board must have exactly one GO space, found {goIndexes.Count}");

        GoIndex = goIndexes[0];
    }

    public static Board FromFile(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception e) when (e is IOException or UnauthorizedAccessException)
        {
            throw new InvalidBoardException($"could not read board file {path}: {e.Message}");
        }

        return FromJson(text);
    }

    public static Board FromJson(string text)
    {
        try
        {
            using var document = JsonDocument.Parse(text);
            if (document.RootElement.ValueKind != JsonValueKind.Array)
                throw new InvalidBoardException("board must be a JSON array of spaces");

            return new Board(document.RootElement.EnumerateArray().Select(BuildSpace).ToList());
        }
        catch (JsonException e)
        {
            throw new InvalidBoardException($"board is not valid JSON: {e.Message}");
        }
    }

    private static Space BuildSpace(JsonElement attrs)
    {
        if (attrs.ValueKind != JsonValueKind.Object)
            throw new InvalidBoardException($"each space must be an object, got {attrs.GetRawText()}");

        var type = attrs.TryGetProperty("type", out var t) && t.ValueKind == JsonValueKind.String ? t.GetString()! : null;
        if (type is null || !SpaceTypes.TryGetValue(type, out var build))
            throw new InvalidBoardException($"unknown space type {(type is null ? "nothing" : $"\"{type}\"")}");

        return build(attrs);
    }

    public IReadOnlyList<Space> Spaces => _spaces;

    public int GoIndex { get; }

    public int Size => _spaces.Length;

    public Space this[int index] => _spaces[index];

    // All properties of one colour, in board order.
    public IReadOnlyList<PropertySpace> ColourGroup(string colour) =>
        _spaces.OfType<PropertySpace>().Where(s => s.Colour == colour).ToList();

    // Moves `steps` spaces forward from `from`, wrapping round the board.
    // Returns the new index and how many times GO was passed. Reaching GO exactly
    // counts as passing it, and a move longer than one lap passes it more than once.
    public (int Position, int GoPasses) Advance(int from, int steps)
    {
        var to = (from + steps) % Size;
        var distanceToGo = (GoIndex - from + Size) % Size; // + Size because C#'s % can return a negative number
        if (distanceToGo == 0) distanceToGo = Size;
        var passes = steps >= distanceToGo ? 1 + ((steps - distanceToGo) / Size) : 0;
        return (to, passes);
    }
}

