    {
        if (rolls.Any(r => r <= 0))
            throw new InvalidRollsException("rolls must be a JSON array of positive whole numbers");

        return rolls;
    }

    private GameResult BuildResult() => new(
        Winners: Winners(),
        Players: Players.Select(p => new PlayerResult(p.Name, p.Money, Board[p.Position].Name, p.IsBankrupt)).ToList(),
        BankruptPlayer: Players.FirstOrDefault(p => p.IsBankrupt)?.Name,
        RollsPlayed: _rollsPlayed,
        RollsTotal: _rolls.Count);

    // The richest player wins; a bankrupt player cannot win. Ties are reported.
    private IReadOnlyList<string> Winners()
    {
        var eligible = Players.Where(p => !p.IsBankrupt).ToList();
        if (eligible.Count == 0) eligible = Players.ToList();
        var top = eligible.Max(p => p.Money);
        return eligible.Where(p => p.Money == top).Select(p => p.Name).ToList();
    }
}

