// Ruby: lib/woven_monopoly/cli.rb
using System.Text.Json;
using WovenMonopoly.Models;
using WovenMonopoly.Views;

namespace WovenMonopoly.Controllers;

// Command line front end: parses arguments, loads the two files, runs the
// game and hands the result to a view. Returns an exit status instead of
// calling Environment.Exit so it can be tested.
public sealed class GameController(TextWriter output, TextWriter error)
{
    public const string Usage = "Usage: WovenMonopoly BOARD_FILE ROLLS_FILE [--json]";

    public static int Run(string[] args, TextWriter output, TextWriter error) =>
        new GameController(output, error).Run(args);

    public int Run(string[] args)
    {
        if (args.Contains("-h") || args.Contains("--help")) return Help();

        var json = args.Contains("--json");
        var paths = args.Where(a => a != "--json").ToArray();
        if (paths.Length != 2) return UsageError();

        try
        {
            var game = new Game(Board.FromFile(paths[0]), LoadRolls(paths[1]));
            IGameView view = json ? new JsonView() : new SummaryView();
            output.WriteLine(view.Render(game.Play()));
            return 0;
        }
        catch (WovenMonopolyException e)
        {
            error.WriteLine($"Error: {e.Message}");
            return 1;
        }
    }

    private static List<int> LoadRolls(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception e) when (e is IOException or UnauthorizedAccessException)
        {
            throw new InvalidRollsException($"could not read rolls file {path}: {e.Message}");
        }

        try
        {
            using var document = JsonDocument.Parse(text);
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Array || root.EnumerateArray().Any(r => !IsWholeNumber(r)))
                throw new InvalidRollsException("rolls must be a JSON array of positive whole numbers");

            return root.EnumerateArray().Select(r => r.GetInt32()).ToList();
        }
        catch (JsonException e)
        {
            throw new InvalidRollsException($"rolls file is not valid JSON: {e.Message}");
        }
    }

    private static bool IsWholeNumber(JsonElement element) =>
        element.ValueKind == JsonValueKind.Number && element.TryGetInt32(out _);

    private int Help()
    {
        output.WriteLine(Usage);
        return 0;
    }

    private int UsageError()
    {
        error.WriteLine(Usage);
        return 2;
    }
}

