// Ruby: test/board_test.rb
using WovenMonopoly.Models;
using static WovenMonopoly.Tests.TestHelpers;

namespace WovenMonopoly.Tests;

public class BoardTests
{
    [Fact]
    public void LoadsTheSampleBoard()
    {
        var board = Board.FromFile(DataPath("board.json"));
        Assert.Equal(9, board.Size);
        Assert.Equal("GO", board[0].Name);
        var burvale = Assert.IsType<PropertySpace>(board[1]);
        Assert.Equal("The Burvale", burvale.Name);
        Assert.Equal(1, burvale.Price);
        Assert.Equal("Brown", burvale.Colour);
    }

    [Fact]
    public void ColourGroupReturnsEveryPropertyOfThatColour()
    {
        var board = Board.FromFile(DataPath("board.json"));
        Assert.Equal(["Gami Chicken", "Massizim"], board.ColourGroup("Blue").Select(p => p.Name));
    }

    [Fact]
    public void ColourGroupsCanBeAnySize()
    {
        var board = Board.FromJson("""
            [
              { "name": "GO", "type": "go" },
              { "name": "A", "type": "property", "price": 1, "colour": "Pink" },
              { "name": "B", "type": "property", "price": 1, "colour": "Pink" },
              { "name": "C", "type": "property", "price": 1, "colour": "Pink" }
            ]
            """);
        Assert.Equal(3, board.ColourGroup("Pink").Count);
    }

    [Fact]
    public void AdvanceWithoutWrapping() => Assert.Equal((3, 0), SmallBoard().Advance(1, 2));

    [Fact]
    public void AdvanceWrapsAndPassesGo() => Assert.Equal((1, 1), SmallBoard().Advance(3, 3));

    [Fact]
    public void LandingExactlyOnGoCountsAsPassingIt() => Assert.Equal((0, 1), SmallBoard().Advance(3, 2));

    [Fact]
    public void LeavingGoDoesNotPassIt() => Assert.Equal((4, 0), SmallBoard().Advance(0, 4));

    [Fact]
    public void AFullLapFromGoPassesGoOnce() => Assert.Equal((0, 1), SmallBoard().Advance(0, 5));

    [Fact]
    public void AMoveLongerThanALapPassesGoMoreThanOnce() => Assert.Equal((2, 2), SmallBoard().Advance(0, 12));

    [Fact]
    public void RejectsABoardWithoutGo()
    {
        var error = Assert.Throws<InvalidBoardException>(() =>
            Board.FromJson("""[{ "name": "A", "type": "property", "price": 1, "colour": "Red" }]"""));
        Assert.Contains("exactly one GO", error.Message);
    }

    [Fact]
    public void RejectsUnknownSpaceTypes()
    {
        var error = Assert.Throws<InvalidBoardException>(() =>
            Board.FromJson("""[{ "name": "GO", "type": "go" }, { "name": "X", "type": "jail" }]"""));
        Assert.Contains("unknown space type", error.Message);
    }

    [Fact]
    public void RejectsAPropertyWithoutAPrice() =>
        Assert.Throws<InvalidBoardException>(() =>
            Board.FromJson("""[{ "name": "GO", "type": "go" }, { "name": "X", "type": "property", "colour": "Red" }]"""));

    [Fact]
    public void RejectsMalformedJson() =>
        Assert.Throws<InvalidBoardException>(() => Board.FromJson("{nope"));

    [Fact]
    public void RejectsAMissingFile() =>
        Assert.Throws<InvalidBoardException>(() => Board.FromFile("/no/such/board.json"));
}

