// Ruby: test/game_test.rb
using WovenMonopoly.Models;
using static WovenMonopoly.Tests.TestHelpers;

namespace WovenMonopoly.Tests;

// Boards used here (see TestHelpers.SmallBoard), size 5:
//   0 GO | 1 A Brown $1 | 2 B Brown $1 | 3 C Red $2 | 4 D Red $2
// Most tests use two players (Ann, Bob) so the turn order is easy to follow.
public class GameTests
{
    private static readonly string[] AnnAndBob = ["Ann", "Bob"];

    private static (Game Game, GameResult Result) Play(int[] rolls, string[]? names = null,
        int startingMoney = 16, int passGoBonus = 1)
    {
        var rules = new Rules { PlayerNames = names ?? AnnAndBob, StartingMoney = startingMoney, PassGoBonus = passGoBonus };
        var game = new Game(SmallBoard(), rolls, rules);
        return (game, game.Play());
    }

    private static int Money(GameResult result, string name) => result.Players.Single(p => p.Name == name).Money;

    private static string SpaceOf(GameResult result, string name) => result.Players.Single(p => p.Name == name).Space;

    // --- Movement and GO -----------------------------------------------------

    [Fact]
    public void EveryoneStartsOnGoWithTheStartingMoney()
    {
        var (_, result) = Play([]);
        Assert.Equal([16, 16], result.Players.Select(p => p.Money));
        Assert.Equal(["GO", "GO"], result.Players.Select(p => p.Space));
    }

    [Fact]
    public void FourDefaultPlayersTakeTurnsInOrder()
    {
        var (_, result) = Play([1, 1, 1, 1], names: [.. Rules.DefaultPlayerNames]);
        // Peter buys A for 1, then Billy, Charlotte and Sweedal each pay Peter 1 rent.
        Assert.Equal([18, 15, 15, 15], result.Players.Select(p => p.Money));
        Assert.Equal(["Peter", "Billy", "Charlotte", "Sweedal"], result.Players.Select(p => p.Name));
    }

    [Fact]
    public void TheStartingMoveDoesNotEarnTheGoBonus()
    {
        var (_, result) = Play([1]);
        Assert.Equal(15, Money(result, "Ann")); // 16 - 1 for A, no bonus
    }

    [Fact]
    public void PassingGoPaysTheBonus()
    {
        // Ann buys A (15). Bob buys C (14). Ann rolls 4 from A: 1 + 4 = 5, which is GO
        // exactly, so she collects the bonus (16).
        var (_, result) = Play([1, 3, 4]);
        Assert.Equal(16, Money(result, "Ann"));
        Assert.Equal("GO", SpaceOf(result, "Ann"));
    }

    [Fact]
    public void WrappingPastGoPaysTheBonusAndLandsOnTheRightSpace()
    {
        // Ann: A (15). Bob: C (14). Ann rolls 5 from 1 -> index 6 % 5 = 1, A again, one GO pass.
        var (_, result) = Play([1, 3, 5]);
        Assert.Equal("A", SpaceOf(result, "Ann"));
        Assert.Equal(16, Money(result, "Ann")); // 15 + 1 bonus, and no rent to herself
    }

    [Fact]
    public void ALongRollPassesGoEachLap()
    {
        var (_, result) = Play([12]); // 12 % 5 = 2 -> B, passing GO twice: 16 + 2 - 1
        Assert.Equal("B", SpaceOf(result, "Ann"));
        Assert.Equal(17, Money(result, "Ann"));
    }

    [Fact]
    public void LandingOnGoDoesNothingElse()
    {
        var (_, result) = Play([5]);
        Assert.Equal(17, Money(result, "Ann"));
        Assert.Equal("GO", SpaceOf(result, "Ann"));
    }

    // --- Buying and rent -----------------------------------------------------

    [Fact]
    public void LandingOnAnUnownedPropertyBuysIt()
    {
        var (game, result) = Play([1]);
        Assert.Equal(15, Money(result, "Ann"));
        Assert.Equal("Ann", game.OwnerOf((PropertySpace)game.Board[1])?.Name);
    }

    [Fact]
    public void LandingOnAnOwnedPropertyPaysRentToTheOwner()
    {
        var (_, result) = Play([1, 1]);
        Assert.Equal(16, Money(result, "Ann")); // 15 + 1 rent
        Assert.Equal(15, Money(result, "Bob")); // 16 - 1 rent
    }

    [Fact]
    public void RentIsNotDoubledWithoutTheFullColourSet()
    {
        // Ann owns A but B is unowned.
        var (_, result) = Play([1, 1]);
        Assert.Equal(1, 16 - Money(result, "Bob"));
    }

    [Fact]
    public void RentIsDoubledWhenTheOwnerHoldsTheWholeColour()
    {
        // Ann buys A, Bob pays 1 rent, Ann buys B (now owns Brown), Bob lands on B and pays 2.
        var (_, result) = Play([1, 1, 1, 1]);
        Assert.Equal(17, Money(result, "Ann")); // 16 - 1 (A) + 1 (rent) - 1 (B) + 2 (double rent)
        Assert.Equal(13, Money(result, "Bob")); // 16 - 1 - 2
    }

    [Fact]
    public void OwnerLandingOnTheirOwnPropertyPaysNothing()
    {
        // Ann buys A. Bob buys C. Ann laps the board (5 from A) back to A.
        var (game, result) = Play([1, 3, 5]);
        Assert.Equal("Ann", game.OwnerOf((PropertySpace)game.Board[1])?.Name);
        Assert.Equal(14, Money(result, "Bob")); // untouched by Ann's landing
    }

    [Fact]
    public void ABuyerWhoCannotAffordThePriceGoesBankruptAndGetsNothing()
    {
        var (game, result) = Play([3, 1, 1], startingMoney: 1); // C costs 2, Ann has 1
        Assert.Equal(0, Money(result, "Ann"));
        Assert.Null(game.OwnerOf((PropertySpace)game.Board[3]));
        Assert.Equal("Ann", result.BankruptPlayer);
    }

    [Fact]
    public void ARenterWhoCannotPayHandsOverWhatTheyHave()
    {
        // Ann buys A (1 left). Bob buys C (0 left). Ann lands on C, owes 2, has 1.
        var (_, result) = Play([1, 3, 2, 1, 1], startingMoney: 2);
        Assert.Equal(0, Money(result, "Ann"));
        Assert.Equal(1, Money(result, "Bob")); // received only the 1 Ann could pay
        Assert.Equal("Ann", result.BankruptPlayer);
    }

    [Fact]
    public void PayingExactlyWhatYouHaveIsNotBankruptcy()
    {
        // Ann buys C (0 left). Bob lands on C and pays exactly 2, leaving 0.
        var (_, result) = Play([3, 3], startingMoney: 2);
        Assert.Null(result.BankruptPlayer);
        Assert.Equal([2, 0], result.Players.Select(p => p.Money));
    }

    // --- Ending the game -----------------------------------------------------

    [Fact]
    public void TheGameStopsAtBankruptcyAndIgnoresTheRemainingRolls()
    {
        var (_, result) = Play([3, 1, 1, 1, 1], startingMoney: 1);
        Assert.Equal(1, result.RollsPlayed);
        Assert.Equal(5, result.RollsTotal);
        Assert.Equal("bankruptcy", result.EndedBy);
    }

    [Fact]
    public void TheRichestPlayerWinsWhenAPlayerGoesBankrupt()
    {
        var (_, result) = Play([3, 1, 1], startingMoney: 1);
        Assert.Equal(["Bob"], result.Winners);
    }

    [Fact]
    public void TheRichestPlayerWinsWhenTheRollsRunOut()
    {
        var (_, result) = Play([3, 3], startingMoney: 2);
        Assert.Equal("rolls_exhausted", result.EndedBy);
        Assert.Equal(["Ann"], result.Winners);
    }

    [Fact]
    public void ATieIsReportedWithEveryTiedPlayer()
    {
        var (_, result) = Play([]);
        Assert.Equal(["Ann", "Bob"], result.Winners);
    }

    // --- Input checking ------------------------------------------------------

    [Theory]
    [InlineData(0)]
    [InlineData(-1)]
    public void RejectsRollsThatAreNotPositive(int badRoll) =>
        Assert.Throws<InvalidRollsException>(() => new Game(SmallBoard(), [badRoll]));

    // --- Rules are configurable ---------------------------------------------

    [Fact]
    public void ADifferentGoBonusIsRespected()
    {
        var (_, result) = Play([5], passGoBonus: 5);
        Assert.Equal(21, Money(result, "Ann"));
    }
}

