// Ruby: test/cli_test.rb
using System.Diagnostics;
using System.Text.Json;
using WovenMonopoly.Controllers;
using static WovenMonopoly.Tests.TestHelpers;

namespace WovenMonopoly.Tests;

public class GameControllerTests
{
    private static (int Status, string Out, string Err) RunController(params string[] args)
    {
        var output = new StringWriter();
        var error = new StringWriter();
        var status = GameController.Run(args, output, error);
        return (status, output.ToString(), error.ToString());
    }

    [Fact]
    public void JsonOutputHasTheRequiredShape()
    {
        var (status, output, _) = RunController(DataPath("board.json"), DataPath("rolls_1.json"), "--json");
        Assert.Equal(0, status);
        var data = JsonDocument.Parse(output).RootElement;
        Assert.Equal(JsonValueKind.Array, data.GetProperty("winners").ValueKind);
        var players = data.GetProperty("players").EnumerateArray().ToList();
        Assert.Equal(["Peter", "Billy", "Charlotte", "Sweedal"], players.Select(p => p.GetProperty("name").GetString()));
        foreach (var p in players)
        {
            Assert.Equal(JsonValueKind.Number, p.GetProperty("money").ValueKind);
            Assert.Equal(JsonValueKind.String, p.GetProperty("space").ValueKind);
        }
    }

    [Fact]
    public void TheJsonFlagCanComeFirst()
    {
        var (status, output, _) = RunController("--json", DataPath("board.json"), DataPath("rolls_1.json"));
        Assert.Equal(0, status);
        Assert.True(JsonDocument.Parse(output).RootElement.TryGetProperty("winners", out _));
    }

    [Fact]
    public void PlainOutputIsAReadableSummary()
    {
        var (status, output, _) = RunController(DataPath("board.json"), DataPath("rolls_1.json"));
        Assert.Equal(0, status);
        Assert.Contains("Winner: ", output);
        Assert.Contains("Charlotte", output);
    }

    [Fact]
    public void MissingArgumentsPrintUsage()
    {
        var (status, _, error) = RunController(DataPath("board.json"));
        Assert.Equal(2, status);
        Assert.Contains("Usage", error);
    }

    [Fact]
    public void AMissingRollsFileIsACleanError()
    {
        var (status, _, error) = RunController(DataPath("board.json"), "/no/such/rolls.json");
        Assert.Equal(1, status);
        Assert.Contains("could not read rolls file", error);
    }

    [Theory]
    [InlineData("""{"not": "an array"}""")]
    [InlineData("[1, 1.5]")]
    [InlineData("""[1, "2"]""")]
    [InlineData("[1, null]")]
    [InlineData("[1, 0]")]
    public void ABadRollsFileIsACleanError(string contents)
    {
        var path = Path.GetTempFileName();
        try
        {
            File.WriteAllText(path, contents);
            var (status, _, error) = RunController(DataPath("board.json"), path);
            Assert.Equal(1, status);
            Assert.Contains("positive whole numbers", error);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Fact]
    public void TheExecutableRunsEndToEnd()
    {
        // The app's DLL is copied next to the test DLL because the test project references it.
        var app = Path.Combine(AppContext.BaseDirectory, "WovenMonopoly.dll");
        var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true };
        foreach (var arg in new[] { app, DataPath("board.json"), DataPath("rolls_2.json"), "--json" })
            start.ArgumentList.Add(arg);

        using var process = Process.Start(start)!;
        var output = process.StandardOutput.ReadToEnd();
        process.WaitForExit();

        Assert.Equal(0, process.ExitCode);
        Assert.NotEmpty(JsonDocument.Parse(output).RootElement.GetProperty("winners").EnumerateArray());
    }
}

