// Ruby: test/scenario_test.rb
using WovenMonopoly.Models;
using static WovenMonopoly.Tests.TestHelpers;

namespace WovenMonopoly.Tests;

// Whole-game checks against the sample board.
public class ScenarioTests
{
    private static GameResult RunGame(string rollsFile)
    {
        var board = Board.FromFile(DataPath("board.json"));
        var rolls = System.Text.Json.JsonSerializer.Deserialize<int[]>(File.ReadAllText(DataPath(rollsFile)))!;
        return new Game(board, rolls).Play();
    }

    private static Dictionary<string, (int, string)> FinalState(GameResult result) =>
        result.Players.ToDictionary(p => p.Name, p => (p.Money, p.Space));

    // rolls_3.json was designed by hand and its result worked out on paper
    // before the program was run. See the Ruby README for the walk-through.
    [Fact]
    public void Rolls3HandDesignedGame()
    {
        var result = RunGame("rolls_3.json");
        Assert.Equal(["Peter"], result.Winners);
        Assert.Equal(
            new Dictionary<string, (int, string)>
            {
                ["Peter"] = (48, "Gami Chicken"),
                ["Billy"] = (0, "Massizim"),
                ["Charlotte"] = (8, "GO"),
                ["Sweedal"] = (0, "Massizim")
            },
            FinalState(result));
        Assert.Equal("Sweedal", result.BankruptPlayer);
        Assert.Equal(12, result.RollsPlayed);
        Assert.Equal(15, result.RollsTotal);
    }

